export function AboveTheFold({
  headline = "{{headline}}",
  subtext = "{{subtext}}",
  device = "{{device}}",
  showFold = {{showFold}},
  bg = "{{bg}}",
}) {
  const width = { desktop: 560, tablet: 420, mobile: 280 }[device] ?? 560;
  return (
    <div style={{ font: "16px/1.5 system-ui, sans-serif", color: "#241430", borderRadius: 12, overflow: "hidden",
      border: "1px solid #24143022", margin: "0 auto", maxWidth: width, background: bg }}>
      <div style={{ display: "flex", gap: 6, padding: "10px 14px", background: "#24143010" }}>
        <span style={{ width: 9, height: 9, borderRadius: "50%", background: "#24143040" }} />
        <span style={{ width: 9, height: 9, borderRadius: "50%", background: "#24143040" }} />
        <span style={{ width: 9, height: 9, borderRadius: "50%", background: "#24143040" }} />
      </div>
      <div style={{ padding: "28px 24px 40px", position: "relative" }}>
        <h2 style={{ margin: "0 0 8px", fontSize: 24, fontWeight: 700 }}>{headline}</h2>
        <p style={{ margin: 0, color: "#241430cc" }}>{subtext}</p>
        {showFold && (
          <div aria-hidden="true" style={{ borderTop: "2px dashed #24143055", margin: "24px 0 16px", position: "relative", textAlign: "center" }}>
            <span style={{ position: "absolute", top: -10, left: "50%", transform: "translateX(-50%)", background: bg,
              padding: "0 8px", fontSize: 11, letterSpacing: "0.05em", textTransform: "uppercase", color: "#24143088" }}>fold</span>
          </div>
        )}
        <p style={{ opacity: 0.35, margin: 0, fontSize: 14 }}>More content continues below…</p>
      </div>
    </div>
  );
}
